{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/feature-cards.json
    The features as a grid of cards, tiles or bordered cells (the body of FeatureGrid). Icons are Lucide names.
    Props (p): features, cols, item. *}
{var $v_features = ($p['features'] ?? null)}
{var $v_cols = ($p['cols'] ?? '1-3')}
{var $v_item = ($p['item'] ?? 'card')}
{capture $c_15}
  {foreach ui_l($v_features) as $v_feature}
    {if ui_t(ui_eq($v_item, 'tile'))}
      {capture $c_5}
        {capture $c_4}
          {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_feature, ['icon'])), 'Size' => 20]])|noescape}
          {capture $c_3}
            {capture $c_1}
              {=ui_text(ui_get($v_feature, ['title']))}
            {/capture}
            {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'base', 'Weight' => 'bold'], 'children' => $c_1])|noescape}
            {capture $c_2}
              {=ui_text(ui_get($v_feature, ['text']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_2])|noescape}
          {/capture}
          {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2'], 'children' => $c_3])|noescape}
        {/capture}
        {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Align' => 'start'], 'children' => $c_4])|noescape}
      {/capture}
      {=ui_include('ui/card/card.latte', ['p' => ['Variant' => 'compact', 'Attrs' => ui_attrs(['data-testid', 'feature-card'])], 'children' => $c_5])|noescape}
    {elseif ui_t(ui_eq($v_item, 'cell'))}
      {capture $c_9}
        {capture $c_6}
          {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_feature, ['icon'])), 'Size' => 24]])|noescape}
        {/capture}
        {=ui_include('ui/iconbadge/icon-badge.latte', ['p' => ['Variant' => 'primary', 'Size' => 'xl', 'Attrs' => ui_attrs(['data-testid', 'feature-icon'])], 'children' => $c_6])|noescape}
        {capture $c_7}
          {=ui_text(ui_get($v_feature, ['title']))}
        {/capture}
        {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'xl', 'Weight' => 'semibold', 'Class' => 'leading-6'], 'children' => $c_7])|noescape}
        {capture $c_8}
          {=ui_text(ui_get($v_feature, ['text']))}
        {/capture}
        {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold', 'Class' => 'leading-5 text-muted-foreground'], 'children' => $c_8])|noescape}
      {/capture}
      {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Align' => 'center', 'Class' => 'h-full gap-8 bg-background px-6 py-12 text-center', 'Attrs' => ui_attrs(['data-testid', 'feature-card'])], 'children' => $c_9])|noescape}
    {else}
      {capture $c_14}
        {capture $c_11}
          {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_feature, ['icon'])), 'Size' => 24]])|noescape}
          {capture $c_10}
            {=ui_text(ui_get($v_feature, ['title']))}
          {/capture}
          {=ui_include('ui/card/card-title.latte', ['p' => ['As' => ui_i(3)], 'children' => $c_10])|noescape}
        {/capture}
        {=ui_include('ui/card/card-header.latte', ['p' => ['Class' => 'flex flex-col gap-4'], 'children' => $c_11])|noescape}
        {capture $c_13}
          {capture $c_12}
            {=ui_text(ui_get($v_feature, ['text']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_12])|noescape}
        {/capture}
        {=ui_include('ui/card/card-content.latte', ['p' => [], 'children' => $c_13])|noescape}
      {/capture}
      {=ui_include('ui/card/card.latte', ['p' => ['Variant' => 'default', 'Attrs' => ui_attrs(['data-testid', 'feature-card'])], 'children' => $c_14])|noescape}
    {/if}
  {/foreach}
{/capture}
{=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => ui_s($v_cols), 'Class' => ui_s((ui_t(ui_eq($v_item, 'cell')) ? ui_cnv(['w-full gap-px overflow-hidden bg-border p-px', ui_preset('blocks/presets/defaults.json', ['features', 'cells'])]) : 'gap-6')), 'Attrs' => ui_attrs(['data-testid', 'feature-grid'])], 'children' => $c_15])|noescape}
